const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

function fresh() {
  const repo = new DocumentRepository([
    { id: 'a1', tenant: 'a', owner: 'alice', deleted: false, archived: false },
    { id: 'a2', tenant: 'a', owner: 'bob', deleted: false, archived: false },
    { id: 'b1', tenant: 'b', owner: 'alice', deleted: false, archived: false },
    { id: 'a3', tenant: 'a', owner: 'alice', deleted: true, archived: false },
    { id: 'a4', tenant: 'a', owner: 'alice', deleted: false, archived: true },
  ]);
  return { repo, service: new DocumentService(repo) };
}
const adminA = { tenant: 'a', user: 'x', role: 'admin' };
const adminB = { tenant: 'b', user: 'x', role: 'admin' };
const editorA = { tenant: 'a', user: 'alice', role: 'editor' };
const editorBob = { tenant: 'a', user: 'bob', role: 'editor' };
const viewerA = { tenant: 'a', user: 'alice', role: 'viewer' };

// admin archives any document in own tenant
let { repo, service } = fresh();
service.archive(adminA, 'a1');
assert.equal(repo.documents[0].archived, true);
assert.deepEqual(repo.audit, [{ actor: 'x', document: 'a1' }]);

// admin cannot see foreign tenant, deleted or missing
for (const id of ['b1', 'a3', 'missing']) {
  const s = fresh().service;
  assert.throws(() => s.archive(adminA, id), /not found/);
  assert.throws(() => s.archive(adminB, id), /not found/);
}

// adminB sees b1
{ const r = fresh().repo; new DocumentService(r).archive(adminB, 'b1');
  assert.equal(r.documents[2].archived, true); }

// editor archives own doc, not others'
{ const { repo: r, service: s } = fresh();
  s.archive(editorA, 'a1');
  assert.equal(r.documents[0].archived, true);
  assert.throws(() => s.archive(editorA, 'a2'), /forbidden/);
  assert.equal(r.documents[1].archived, false); }

// viewer never
{ const { repo: r, service: s } = fresh();
  assert.throws(() => s.archive(viewerA, 'a1'), /forbidden/);
  assert.equal(r.documents[0].archived, false);
  assert.deepEqual(r.audit, []); }

// no-op repeat still enforces permission
{ const { repo: r, service: s } = fresh();
  s.archive(editorA, 'a1');
  assert.throws(() => s.archive(editorBob, 'a1'), /forbidden/);
  assert.throws(() => s.archive(viewerA, 'a1'), /forbidden/);
  assert.throws(() => s.archive(editorA, 'a4'), /forbidden/);
  s.archive(editorA, 'a1'); // no-op
  assert.deepEqual(r.audit, [{ actor: 'alice', document: 'a1' }]);
  assert.throws(() => s.archive(editorA, 'a3'), /not found/); }

// foreign tenant + archived is still 'not found'
{ const s = fresh().service;
  assert.throws(() => s.archive(adminA, 'b1'), /not found/);
  assert.throws(() => s.archive(viewerA, 'missing'), /not found/); }

console.log('authz checks passed');
EOF
